CREATE OR REPLACE VIEW "public"."carrier_supplier_routing" WITH ("security_invoker"='on') AS
 SELECT "m"."carrier_id",
    "ca"."name" AS "carrier_name",
    "ca"."country_id",
    "co"."iso_code" AS "country_code",
    "co"."name" AS "country_name",
    "co"."is_supported" AS "country_is_supported",
    "m"."provider" AS "provider_code",
    "sp"."name" AS "provider_name",
    "m"."provider_country_code",
    "m"."provider_country_label",
    "m"."provider_carrier_code",
    "m"."provider_carrier_label",
    "m"."is_enabled",
    "m"."is_primary",
    "m"."priority",
    "m"."last_verified_at",
    ("m"."is_enabled" AND "sp"."is_active" AND "sp"."supports_topup" AND COALESCE("pol"."is_globally_enabled", false)) AS "is_routable"
   FROM (((("public"."carrier_provider_map" "m"
     JOIN "public"."carriers" "ca" ON (("ca"."id" = "m"."carrier_id")))
     JOIN "public"."countries" "co" ON (("co"."id" = "ca"."country_id")))
     JOIN "public"."service_providers" "sp" ON (("sp"."code" = "m"."provider")))
     LEFT JOIN "public"."supplier_policy" "pol" ON (("pol"."provider" = "m"."provider")));

CREATE OR REPLACE VIEW "public"."provider_offers_effective" AS
 SELECT "o"."id",
    "o"."provider_code",
    "sp"."name" AS "provider_name",
    "o"."offer_kind",
    "o"."offer_code",
    "o"."country_code",
    "co"."name" AS "country_name",
    "o"."carrier_id",
    "ca"."name" AS "carrier_name",
    "o"."effective_name" AS "offer_name",
    "o"."source_price_type" AS "price_type",
    "o"."effective_price_usd" AS "price_usd",
    "o"."source_price_min_usd" AS "price_min_usd",
    "o"."source_price_max_usd" AS "price_max_usd",
    "o"."source_send_min" AS "send_min",
    "o"."source_send_max" AS "send_max",
    "o"."source_send_currency" AS "send_currency",
    "o"."source_send_divisor" AS "send_currency_divisor",
    "o"."source_data_mb" AS "data_mb",
    "o"."source_duration_days" AS "duration_days",
    "o"."source_is_unlimited" AS "is_unlimited",
    "o"."source_speed_tier" AS "speed_tier",
    "o"."source_price_usd" AS "supplier_cost_usd",
    ("o"."override_price_usd" IS NOT NULL) AS "price_is_overridden",
    "o"."override_note",
    "o"."source_refreshed_at",
    ("o"."source_refreshed_at" < ("now"() - '24:00:00'::interval)) AS "is_stale"
   FROM ((("public"."provider_offers" "o"
     JOIN "public"."service_providers" "sp" ON (("sp"."code" = "o"."provider_code")))
     JOIN "public"."countries" "co" ON (("co"."iso_code" = "o"."country_code")))
     JOIN "public"."carriers" "ca" ON (("ca"."id" = "o"."carrier_id")))
  WHERE ("o"."is_active" AND "sp"."is_active" AND "co"."is_supported");

CREATE OR REPLACE VIEW "public"."zendit_offers_cache" AS
 SELECT "offer_id",
    "country_code",
    "carrier_code" AS "zen_carrier",
    "offer_name",
    "price_type",
    "price_fixed_usd",
    "price_min_usd",
    "price_max_usd",
    "send_min",
    "send_max",
    "send_currency",
    "refreshed_at",
    "send_currency_divisor"
   FROM "public"."provider_offers_cache"
  WHERE ("api_provider" = 'zendit'::"text");

CREATE OR REPLACE VIEW "public"."esim_offers" AS
 SELECT (("c"."provider" || '_'::"text") || "c"."bundle_name") AS "id",
    "c"."provider",
    "c"."bundle_name",
    "c"."description",
    "c"."countries",
    "c"."roaming_enabled",
    "c"."data_amount_mb",
    "c"."duration_days",
    ("round"(("c"."wholesale_price_usd" * (1.0 + (COALESCE("s"."markup_percent_override", ( SELECT (NULLIF(("system_configs"."config_value")::"text", ''::"text"))::numeric AS "nullif"
           FROM "public"."system_configs"
          WHERE (("system_configs"."config_key")::"text" = 'ESIM_MARKUP_PERCENT'::"text")), 30.0) / 100.0))), 2))::numeric(10,2) AS "retail_price_usd",
    "c"."image_url",
    "c"."is_active",
    "c"."updated_at",
    "c"."is_unlimited",
    "c"."bundle_group",
    "c"."speed_tier",
    "c"."region",
    "c"."country_count",
    (
        CASE
            WHEN ("c"."is_unlimited" OR ("c"."data_amount_mb" <= 0)) THEN NULL::numeric
            ELSE "round"(("round"(("c"."wholesale_price_usd" * (1.0 + (COALESCE("s"."markup_percent_override", ( SELECT (NULLIF(("system_configs"."config_value")::"text", ''::"text"))::numeric AS "nullif"
               FROM "public"."system_configs"
              WHERE (("system_configs"."config_key")::"text" = 'ESIM_MARKUP_PERCENT'::"text")), 30.0) / 100.0))), 2) / (("c"."data_amount_mb")::numeric / 1024.0)), 2)
        END)::numeric(10,2) AS "price_per_gb_usd"
   FROM ("public"."esim_offers_cache" "c"
     LEFT JOIN "public"."esim_suppliers" "s" ON (("s"."code" = "c"."provider")))
  WHERE ("c"."is_active" = true);

CREATE OR REPLACE FUNCTION "public"."list_carrier_offers"("p_carrier_id" "uuid") RETURNS TABLE("provider" "text", "offer_id" "text", "offer_name" "text", "price_type" "text", "price_usd" numeric, "price_min_usd" numeric, "price_max_usd" numeric, "send_min" numeric, "send_max" numeric, "send_currency" "text", "send_currency_divisor" numeric, "refreshed_at" timestamp with time zone, "is_stale" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  RETURN QUERY
  SELECT o.provider_code, o.offer_code, o.effective_name, o.source_price_type,
         o.effective_price_usd, o.source_price_min_usd, o.source_price_max_usd,
         o.source_send_min, o.source_send_max, o.source_send_currency,
         COALESCE(o.source_send_divisor, 100),
         o.source_refreshed_at,
         (o.source_refreshed_at < now() - interval '24 hours')
  FROM public.provider_offers o
  JOIN public.carrier_supplier_routing r
    ON r.carrier_id = o.carrier_id AND r.provider_code = o.provider_code
  WHERE o.carrier_id = p_carrier_id
    AND o.offer_kind = 'topup'
    AND o.is_active
    -- Only offers that can actually be routed and bought. Listing anything else
    -- is how a tap turns into "offer is not available for this SIM line".
    AND r.is_routable
  ORDER BY o.effective_price_usd ASC NULLS LAST, r.priority ASC, o.offer_code ASC;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."list_refill_offers"("p_sim_line_id" "uuid") RETURNS TABLE("provider" "text", "offer_id" "text", "offer_name" "text", "price_type" "text", "price_fixed_usd" numeric, "price_min_usd" numeric, "price_max_usd" numeric, "send_min" numeric, "send_max" numeric, "send_currency" "text", "send_currency_divisor" numeric, "refreshed_at" timestamp with time zone, "is_stale" boolean, "delivery_type" "text", "service_type" "text", "benefit_summary" "text", "data_mb" bigint, "duration_days" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.sim_lines sl
    WHERE sl.id = p_sim_line_id
      AND (sl.user_id = auth.uid()
           OR EXISTS (SELECT 1 FROM public.household_members hm
                      WHERE hm.owner_id = sl.user_id
                        AND hm.member_id = auth.uid()
                        AND hm.invite_status = 'accepted'
                        AND hm.role = 'manager'))
  ) THEN
    RAISE EXCEPTION 'Not authorized to read offers for this SIM line';
  END IF;

  RETURN QUERY
  SELECT
    poc.api_provider,
    poc.offer_id,
    poc.offer_name,
    poc.price_type,
    poc.price_fixed_usd,
    poc.price_min_usd,
    poc.price_max_usd,
    poc.send_min,
    poc.send_max,
    poc.send_currency,
    poc.send_currency_divisor,
    poc.refreshed_at,
    (poc.refreshed_at < now() - interval '24 hours') AS is_stale,
    COALESCE(poc.delivery_type, 'direct') AS delivery_type,
    COALESCE(poc.service_type, 'airtime') AS service_type,
    COALESCE(poc.benefit_summary, poc.offer_name) AS benefit_summary,
    poc.data_mb,
    poc.duration_days
  FROM public.sim_lines sl
  JOIN public.carrier_provider_map m
    ON m.carrier_id = sl.carrier_id
   AND m.is_enabled = true
  JOIN public.provider_offers_cache poc
    ON poc.api_provider  = m.provider
   AND poc.country_code  = m.provider_country_code
   AND poc.carrier_code  = m.provider_carrier_code
  WHERE sl.id = p_sim_line_id
  ORDER BY
    coalesce(poc.price_fixed_usd, poc.price_min_usd) ASC NULLS LAST,
    m.priority ASC,
    poc.offer_id ASC;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."pick_best_refill_offer"("p_sim_line_id" "uuid", "p_target_usd" numeric) RETURNS TABLE("provider" "text", "offer_id" "text", "price_type" "text", "charge_usd" numeric, "offer_value" numeric, "reached_target" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row RECORD;
BEGIN
  IF p_target_usd IS NULL OR p_target_usd <= 0 THEN
    RAISE EXCEPTION 'Target amount must be positive';
  END IF;

  SELECT * INTO v_row
  FROM public.list_refill_offers(p_sim_line_id) o
  WHERE o.is_stale = false
    AND (
      (o.price_type = 'FIXED' AND o.price_fixed_usd >= p_target_usd)
      OR (o.price_type <> 'FIXED' AND o.price_max_usd >= p_target_usd
                                  AND o.price_min_usd <= p_target_usd)
    )
  ORDER BY
    CASE WHEN o.price_type = 'FIXED' THEN o.price_fixed_usd ELSE p_target_usd END ASC
  LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT
      v_row.provider,
      v_row.offer_id,
      v_row.price_type,
      CASE WHEN v_row.price_type = 'FIXED' THEN v_row.price_fixed_usd ELSE round(p_target_usd, 2) END,
      CASE WHEN v_row.price_type = 'FIXED' THEN NULL::numeric
           ELSE public.interpolate_offer_value(
                  v_row.send_min, v_row.send_max,
                  v_row.price_min_usd, v_row.price_max_usd, round(p_target_usd, 2)) END,
      true;
    RETURN;
  END IF;

  SELECT * INTO v_row
  FROM public.list_refill_offers(p_sim_line_id) o
  WHERE o.is_stale = false
  ORDER BY coalesce(o.price_fixed_usd, o.price_min_usd) ASC NULLS LAST
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  RETURN QUERY SELECT
    v_row.provider,
    v_row.offer_id,
    v_row.price_type,
    coalesce(v_row.price_fixed_usd, v_row.price_min_usd),
    CASE WHEN v_row.price_type = 'FIXED' THEN NULL::numeric ELSE v_row.send_min END,
    false;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."choose_supplier_for_offer"("p_sim_line_id" "uuid", "p_offer_id" "text", "p_exclude" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("provider" "text", "base_cost_usd" numeric, "effective_usd" numeric, "is_incumbent" boolean, "chosen_reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mode       text;
  v_min_usd    numeric;
  v_min_pct    numeric;
  v_incumbent  RECORD;
  v_challenger RECORD;
BEGIN
  BEGIN
    SELECT config_value INTO v_mode FROM public.system_configs
    WHERE config_key = 'SUPPLIER_SELECTION_MODE';
  EXCEPTION WHEN OTHERS THEN v_mode := NULL;
  END;
  v_mode := lower(COALESCE(v_mode, 'margin_aware'));

  v_min_usd := public.config_numeric('SUPPLIER_SWITCH_MIN_SAVING_USD',    0.05, 0, 100);
  v_min_pct := public.config_numeric('SUPPLIER_SWITCH_MIN_SAVING_PERCENT', 2.0, 0, 100);

  SELECT * INTO v_challenger
  FROM public.supplier_candidates(p_sim_line_id, p_offer_id, p_exclude) c
  ORDER BY c.eff ASC, c.prio ASC, c.provider ASC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_mode = 'cheapest' THEN
    RETURN QUERY SELECT v_challenger.provider, v_challenger.base, v_challenger.eff,
                        v_challenger.incumbent, 'cheapest'::text;
    RETURN;
  END IF;

  SELECT * INTO v_incumbent
  FROM public.supplier_candidates(p_sim_line_id, p_offer_id, p_exclude) c
  WHERE c.incumbent
  ORDER BY c.eff ASC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY SELECT v_challenger.provider, v_challenger.base, v_challenger.eff,
                        v_challenger.incumbent, 'no_incumbent'::text;
    RETURN;
  END IF;

  IF v_challenger.provider = v_incumbent.provider THEN
    RETURN QUERY SELECT v_incumbent.provider, v_incumbent.base, v_incumbent.eff,
                        true, 'incumbent_is_cheapest'::text;
    RETURN;
  END IF;

  IF (v_incumbent.eff - v_challenger.eff) >= v_min_usd
     AND v_incumbent.eff > 0
     AND ((v_incumbent.eff - v_challenger.eff) / v_incumbent.eff * 100.0) >= v_min_pct
  THEN
    RETURN QUERY SELECT v_challenger.provider, v_challenger.base, v_challenger.eff,
                        false, 'challenger_beat_threshold'::text;
  ELSE
    RETURN QUERY SELECT v_incumbent.provider, v_incumbent.base, v_incumbent.eff,
                        true, 'saving_below_threshold'::text;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."supplier_candidates"("p_sim_line_id" "uuid", "p_offer_id" "text", "p_exclude" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("provider" "text", "base" numeric, "eff" numeric, "incumbent" boolean, "prio" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT poc.api_provider,
         COALESCE(poc.price_fixed_usd, poc.price_min_usd),
         public.supplier_effective_cost(poc.api_provider, COALESCE(poc.price_fixed_usd, poc.price_min_usd)),
         m.is_primary,
         m.priority
  FROM public.sim_lines sl
  JOIN public.carrier_provider_map m ON m.carrier_id = sl.carrier_id AND m.is_enabled
  JOIN public.supplier_policy sp ON sp.provider = m.provider AND sp.is_globally_enabled
  JOIN public.provider_offers_cache poc
    ON poc.api_provider = m.provider AND poc.country_code = m.provider_country_code
   AND poc.carrier_code = m.provider_carrier_code AND poc.offer_id = p_offer_id
  WHERE sl.id = p_sim_line_id
    AND poc.refreshed_at >= now() - interval '24 hours'
    AND (p_exclude IS NULL OR NOT (poc.api_provider = ANY (p_exclude)));
$$;

CREATE OR REPLACE FUNCTION "public"."supplier_effective_cost"("p_provider" "text", "p_base" numeric) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prem numeric := 0;
  v_flat numeric := 0;
BEGIN
  IF p_base IS NULL THEN RETURN NULL; END IF;
  SELECT sp.risk_premium_percent, sp.flat_penalty_usd
  INTO v_prem, v_flat
  FROM public.supplier_policy sp
  WHERE sp.provider = p_provider;
  RETURN round(p_base * (1 + COALESCE(v_prem, 0) / 100.0) + COALESCE(v_flat, 0), 4);
END;
$$;

CREATE OR REPLACE FUNCTION "public"."resolve_household_payer"("p_actor_id" "uuid", "p_line_owner_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p_actor_id = p_line_owner_id THEN p_actor_id
    WHEN EXISTS (
      SELECT 1 FROM public.household_members hm
      WHERE hm.owner_id        = p_line_owner_id
        AND hm.member_id       = p_actor_id
        AND hm.invite_status   = 'accepted'
        AND hm.role            = 'manager'
        AND hm.monthly_cap_usd > 0
    ) THEN p_line_owner_id
    ELSE p_actor_id
  END;
$$;

CREATE OR REPLACE FUNCTION "public"."household_spend_check"("p_owner_id" "uuid", "p_member_id" "uuid", "p_amount" numeric, "p_exclude_execution_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("allowed" boolean, "reason" "text", "monthly_cap" numeric, "per_txn_cap" numeric, "spent_mtd" numeric, "remaining_usd" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_m      RECORD;
  v_spend  RECORD;
  v_remain numeric;
BEGIN
  SELECT hm.monthly_cap_usd, hm.per_txn_cap_usd, hm.role, hm.invite_status
    INTO v_m
  FROM public.household_members hm
  WHERE hm.owner_id = p_owner_id AND hm.member_id = p_member_id;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'NOT_A_MEMBER', 0::numeric, NULL::numeric, 0::numeric, 0::numeric;
    RETURN;
  END IF;

  IF v_m.invite_status <> 'accepted' THEN
    RETURN QUERY SELECT false, 'INVITE_NOT_ACCEPTED', v_m.monthly_cap_usd, v_m.per_txn_cap_usd, 0::numeric, 0::numeric;
    RETURN;
  END IF;

  IF v_m.role <> 'manager' THEN
    RETURN QUERY SELECT false, 'NOT_A_MANAGER', v_m.monthly_cap_usd, v_m.per_txn_cap_usd, 0::numeric, 0::numeric;
    RETURN;
  END IF;

  IF v_m.monthly_cap_usd <= 0 THEN
    RETURN QUERY SELECT false, 'NO_CAP_SET', v_m.monthly_cap_usd, v_m.per_txn_cap_usd, 0::numeric, 0::numeric;
    RETURN;
  END IF;

  SELECT * INTO v_spend
  FROM public.household_spend_mtd(p_owner_id, p_member_id, p_exclude_execution_id);

  v_remain := v_m.monthly_cap_usd - v_spend.total_usd;

  IF p_amount IS NOT NULL AND v_m.per_txn_cap_usd IS NOT NULL AND p_amount > v_m.per_txn_cap_usd THEN
    RETURN QUERY SELECT false, 'OVER_PER_TXN_CAP', v_m.monthly_cap_usd, v_m.per_txn_cap_usd,
                        v_spend.total_usd, GREATEST(v_remain, 0);
    RETURN;
  END IF;

  IF p_amount IS NOT NULL AND p_amount > v_remain THEN
    RETURN QUERY SELECT false, 'OVER_MONTHLY_CAP', v_m.monthly_cap_usd, v_m.per_txn_cap_usd,
                        v_spend.total_usd, GREATEST(v_remain, 0);
    RETURN;
  END IF;

  RETURN QUERY SELECT true, 'OK', v_m.monthly_cap_usd, v_m.per_txn_cap_usd,
                      v_spend.total_usd, GREATEST(v_remain, 0);
END $$;

CREATE OR REPLACE FUNCTION "public"."household_spend_mtd"("p_owner_id" "uuid", "p_member_id" "uuid", "p_exclude_execution_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("committed_usd" numeric, "in_flight_usd" numeric, "total_usd" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
WITH bounds AS (
  SELECT date_trunc('month', (now() AT TIME ZONE 'UTC')) AT TIME ZONE 'UTC' AS month_start
),
debits AS (
  SELECT wt.reference_id, wt.amount
  FROM public.wallet_transactions wt
  JOIN public.wallets w ON w.id = wt.wallet_id
  CROSS JOIN bounds b
  WHERE w.user_id = p_owner_id
    AND wt.status = 'completed'
    AND wt.created_at >= b.month_start
    AND wt.metadata ->> 'spent_by' = p_member_id::text
    AND wt.type IN ('topup_debit', 'welcome_home_debit', 'plan_fee_debit')
),
refunds AS (
  SELECT COALESCE(SUM(wt.amount), 0) AS amt
  FROM public.wallet_transactions wt
  JOIN public.wallets w ON w.id = wt.wallet_id
  WHERE w.user_id = p_owner_id
    AND wt.status = 'completed'
    AND wt.type IN ('refund', 'esim_purchase_refund')
    AND wt.reference_id IN (SELECT reference_id FROM debits WHERE reference_id IS NOT NULL)
),
in_flight AS (
  SELECT COALESCE(SUM(te.amount), 0) AS amt
  FROM public.topup_executions te
  CROSS JOIN bounds b
  WHERE te.acting_user_id = p_member_id
    AND te.user_id        = p_owner_id
    AND te.created_at    >= b.month_start
    AND te.status IN ('pending', 'pending_payment', 'routing', 'processing')
    AND te.payment_gateway_code = 'wallet'
    AND (p_exclude_execution_id IS NULL OR te.id <> p_exclude_execution_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.wallet_transactions wt
      WHERE wt.reference_id = 'exec_' || te.id::text
        AND wt.status = 'completed'
    )
)
SELECT
  GREATEST(COALESCE((SELECT SUM(amount) FROM debits), 0) - (SELECT amt FROM refunds), 0)::numeric(12,2),
  (SELECT amt FROM in_flight)::numeric(12,2),
  (GREATEST(COALESCE((SELECT SUM(amount) FROM debits), 0) - (SELECT amt FROM refunds), 0)
   + (SELECT amt FROM in_flight))::numeric(12,2);
$$;

CREATE OR REPLACE FUNCTION "public"."request_instant_refill"("p_sim_line_id" "uuid", "p_offer_id" "text", "p_payment_gateway_code" "text", "p_amount_usd" numeric DEFAULT NULL::numeric, "p_device_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pick         RECORD;
  v_offer        RECORD;
  v_base         numeric;
  v_value        numeric;
  v_execution_id uuid;
  v_line_owner   uuid;
  v_payer        uuid;
  v_acting       uuid;
  v_charged      numeric;
  v_chk          RECORD;
  v_guard        jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_suspended = true) THEN
    RAISE EXCEPTION 'Account is suspended. Refills are disabled.';
  END IF;

  PERFORM public.enforce_rate_limit('instant_refill', auth.uid()::text);

  SELECT sl.user_id INTO v_line_owner
  FROM public.sim_lines sl
  WHERE sl.id = p_sim_line_id
    AND (sl.user_id = auth.uid()
         OR EXISTS (SELECT 1 FROM public.household_members hm
                    WHERE hm.owner_id = sl.user_id
                      AND hm.member_id = auth.uid()
                      AND hm.invite_status = 'accepted'
                      AND hm.role = 'manager'));

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Not authorized to refill this SIM line';
  END IF;

  SELECT * INTO v_pick FROM public.choose_supplier_for_offer(p_sim_line_id, p_offer_id, NULL);

  IF NOT FOUND THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.sim_lines sl2
      JOIN public.carrier_provider_map m2 ON m2.carrier_id = sl2.carrier_id AND m2.is_enabled
      JOIN public.supplier_policy sp2 ON sp2.provider = m2.provider AND sp2.is_globally_enabled
      WHERE sl2.id = p_sim_line_id
    ) THEN
      RAISE EXCEPTION 'This carrier has no online top-up catalog';
    END IF;
    RAISE EXCEPTION 'Offer % is not available for this SIM line', p_offer_id;
  END IF;

  SELECT poc.price_type, poc.price_fixed_usd, poc.price_min_usd, poc.price_max_usd,
         poc.send_min, poc.send_max, poc.refreshed_at
  INTO v_offer
  FROM public.provider_offers_cache poc
  JOIN public.sim_lines sl ON sl.id = p_sim_line_id
  JOIN public.carrier_provider_map m
    ON m.carrier_id = sl.carrier_id AND m.provider = v_pick.provider
  WHERE poc.api_provider = v_pick.provider
    AND poc.country_code = m.provider_country_code
    AND poc.carrier_code = m.provider_carrier_code
    AND poc.offer_id = p_offer_id;

  IF v_offer.refreshed_at < now() - interval '24 hours' THEN
    RAISE EXCEPTION 'Offer pricing is temporarily unavailable. Please try again later.';
  END IF;

  IF v_offer.price_type = 'FIXED' THEN
    v_base := v_offer.price_fixed_usd;
    v_value := NULL;
  ELSE
    IF p_amount_usd IS NULL THEN
      RAISE EXCEPTION 'This offer requires an amount';
    END IF;
    v_base := round(p_amount_usd, 2);
    IF v_base < v_offer.price_min_usd - 0.01 OR v_base > v_offer.price_max_usd + 0.01 THEN
      RAISE EXCEPTION 'Amount % is outside this offer''s %-% USD range',
        v_base, v_offer.price_min_usd, v_offer.price_max_usd;
    END IF;
    v_value := public.interpolate_offer_value(
      v_offer.send_min, v_offer.send_max,
      v_offer.price_min_usd, v_offer.price_max_usd, v_base);
  END IF;

  IF v_base IS NULL OR v_base <= 0 THEN
    RAISE EXCEPTION 'Offer % has no usable price', p_offer_id;
  END IF;

  v_guard := public.guard_money_action('instant_refill', v_base, p_device_id, NULL, auth.uid());
  IF (v_guard ->> 'blocked')::boolean THEN
    RAISE EXCEPTION USING
      ERRCODE = 'KS451',
      MESSAGE = 'DEVICE_BLOCKED:' || COALESCE(v_guard ->> 'reason', 'unknown'),
      DETAIL  = 'device risk score ' || COALESCE(v_guard ->> 'score', '?'),
      HINT    = 'This payment was stopped by a security check on this device.';
  END IF;

  v_payer  := public.resolve_household_payer(auth.uid(), v_line_owner);
  v_acting := CASE WHEN v_payer <> auth.uid() THEN auth.uid() END;

  INSERT INTO public.topup_executions (
    sim_line_id, user_id, acting_user_id, amount, base_cost_usd, payment_gateway_code,
    currency, status, execution_type, execution_time, offer_id, offer_value,
    api_provider, attempted_providers
  ) VALUES (
    p_sim_line_id, v_payer, v_acting, v_base, v_base, p_payment_gateway_code,
    'USD', 'pending', 'refill_instant', now(), p_offer_id, v_value,
    v_pick.provider, ARRAY[v_pick.provider]
  )
  RETURNING id, amount INTO v_execution_id, v_charged;

  IF v_acting IS NOT NULL THEN
    SELECT * INTO v_chk
    FROM public.household_spend_check(v_payer, v_acting, v_charged, v_execution_id);

    IF NOT v_chk.allowed THEN
      RAISE EXCEPTION 'HOUSEHOLD_CAP:%:%:%:%',
        v_chk.reason, v_chk.monthly_cap, v_chk.spent_mtd, v_chk.remaining_usd
        USING ERRCODE = 'KS402';
    END IF;
  END IF;

  RETURN v_execution_id;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."config_numeric"("p_key" "text", "p_default" numeric, "p_min" numeric, "p_max" numeric) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v numeric;
BEGIN
  BEGIN
    SELECT config_value::numeric INTO v FROM public.system_configs WHERE config_key = p_key;
  EXCEPTION WHEN OTHERS THEN
    v := NULL;
  END;
  IF v IS NULL OR v < p_min OR v > p_max THEN
    RETURN p_default;
  END IF;
  RETURN v;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."interpolate_offer_value"("p_send_min" numeric, "p_send_max" numeric, "p_price_min" numeric, "p_price_max" numeric, "p_price" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT least(p_send_max, greatest(p_send_min, round(
    p_send_min
    + CASE WHEN p_price_max - p_price_min > 0
           THEN (p_price - p_price_min) * (p_send_max - p_send_min)
                / (p_price_max - p_price_min)
           ELSE 0 END)));
$$;

CREATE OR REPLACE FUNCTION "public"."assert_admin"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  v_raw   text;
  v_role  text;
  v_uid   uuid;
BEGIN
  v_raw := current_setting('request.jwt.claims', true);
  IF v_raw IS NOT NULL AND v_raw <> '' THEN
    v_role := (v_raw::jsonb) ->> 'role';
  END IF;

  IF v_role = 'service_role' THEN
    RETURN NULL;
  END IF;

  v_uid := auth.uid();

  IF v_uid IS NULL
     OR NOT public.is_power_user(v_uid)
     OR public.is_user_suspended() THEN
    RAISE EXCEPTION 'Admin access required'
      USING ERRCODE = 'KS460',
            HINT = 'This action needs a power-user session.';
  END IF;

  RETURN v_uid;
END;
$$;

ALTER TABLE public.supplier_policy ENABLE ROW LEVEL SECURITY;

