GRANT SELECT,MAINTAIN ON TABLE "public"."provider_offers_cache" TO "authenticated";

GRANT ALL ON TABLE "public"."provider_offers_cache" TO "service_role";

ALTER TABLE public.esim_orders ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can read own esim orders" ON "public"."esim_orders" FOR SELECT TO "authenticated" USING (("auth"."uid"() = "user_id"));

GRANT SELECT,MAINTAIN ON TABLE "public"."esim_orders" TO "anon";

GRANT SELECT,MAINTAIN ON TABLE "public"."esim_orders" TO "authenticated";

GRANT ALL ON TABLE "public"."esim_orders" TO "service_role";

