GRANT ALL ON TABLE "public"."provider_offers_effective" TO "service_role";

GRANT SELECT ON TABLE "public"."provider_offers_effective" TO "authenticated";

GRANT SELECT ON TABLE "public"."provider_offers_effective" TO "anon";

